using PaymentAuthorization.Domain;

namespace PaymentAuthorization.Application;

/// <summary>Outbound gateway to the payment provider.</summary>
public interface IPaymentGateway
{
    Task<AuthorizationOutcome> AuthorizeAsync(string reference, Money amount, CancellationToken cancellationToken);
}
namespace PaymentAuthorization.Application;

/// <summary>Outbound store keeping one receipt per authorization attempt.</summary>
public interface IReceiptStore
{
    Task SaveAsync(string reference, string body, CancellationToken cancellationToken);
}
namespace PaymentAuthorization.Domain;

/// <summary>What the payment provider decided about one authorization request.</summary>
public enum AuthorizationOutcome
{
    Declined = 0,
    Approved = 1,
}
namespace PaymentAuthorization.Domain;

/// <summary>An amount and the currency it is expressed in.</summary>
public readonly record struct Money
{
    public Money(decimal amount, string currency)
    {
        if (amount <= 0) throw new ArgumentOutOfRangeException(nameof(amount), "An amount must be positive.");
        if (string.IsNullOrWhiteSpace(currency)) throw new ArgumentException("A currency is required.", nameof(currency));

        Amount = amount;
        Currency = currency.ToUpperInvariant();
    }

    public decimal Amount { get; }

    public string Currency { get; }
}
